from typing import List, Tuple

def can_tile_grid(n: int, h: int, w: int, tiles: List[Tuple[int, int]]) -> bool:
    """
    Determine if it's possible to place rectangular tiles on an H×W grid such that:
    - Every cell is covered by exactly one tile
    - Tiles can be rotated (so a 2×3 tile can be placed as 3×2)
    - Some tiles may remain unused
    - Tiles must be aligned with grid cells and cannot extend outside

    Args:
        n: Number of available tiles (1 ≤ n ≤ 7)
        h: Height of the grid (1 ≤ h ≤ 10)
        w: Width of the grid (1 ≤ w ≤ 10)
        tiles: List of (a, b) tuples where tile i has dimensions a×b (1 ≤ a, b ≤ 10)

    Returns:
        True if the grid can be perfectly tiled, False otherwise
    """
    # Quick area check: total area of all tiles must be at least grid area
    grid_area = h * w
    if sum(a * b for a, b in tiles) < grid_area:
        return False

    # Represent grid as a list of lists of bools (False = empty)
    board = [[False] * w for _ in range(h)]

    # Helper: find first empty cell (row-major order)
    def find_empty():
        for i in range(h):
            for j in range(w):
                if not board[i][j]:
                    return i, j
        return None  # board full

    # Helper: check if a tile of size (dh, dw) fits at (r, c)
    def can_place(r: int, c: int, dh: int, dw: int) -> bool:
        if r + dh > h or c + dw > w:
            return False
        for i in range(r, r + dh):
            for j in range(c, c + dw):
                if board[i][j]:
                    return False
        return True

    # Helper: place/remove a tile
    def set_tile(r: int, c: int, dh: int, dw: int, val: bool):
        for i in range(r, r + dh):
            for j in range(c, c + dw):
                board[i][j] = val

    # Depth‑first search with bitmask of used tiles
    from functools import lru_cache

    @lru_cache(maxsize=None)
    def dfs(used_mask: int) -> bool:
        empty = find_empty()
        if empty is None:          # board completely filled
            return True
        r, c = empty

        # Try each unused tile in both orientations
        for idx in range(n):
            if used_mask >> idx & 1:
                continue
            a, b = tiles[idx]
            for dh, dw in ((a, b), (b, a)):
                if dh == dw and (a, b) == (b, a):
                    # avoid trying the same orientation twice for squares
                    pass
                if can_place(r, c, dh, dw):
                    set_tile(r, c, dh, dw, True)
                    if dfs(used_mask | (1 << idx)):
                        return True
                    set_tile(r, c, dh, dw, False)
        # No tile fits here -> dead end
        return False

    return dfs(0)
